#!/usr/bin/env bash
# AI DISCLAIMER: All of the text in this file was generated by AI.
# The lab coordinator's driver for the G019 W arm on the HDD VM (pre-registered 3d86514 + d2a7735).
# Index warm-up (6bd706451, 88b119bc3, e74c7b3be) alone on stock vs stock, A W W A W A A W.
# Uses kit v5's hdd_run.sh UNCHANGED (sha 91e51b07...), the same environment as the G015 stage 4b wrapper
# (uncompacted snapshot s3106400 at 3,106,400, cold cache dropped by hdd_run.sh, peer = the peer only, default
# target 400 blocks = top 3,106,800), each call exactly as stage 4b's "C" arm (TIMEOUT_S=4800, no WARM_DBS, no MEM_MAX).
# Markers in $ST/log.txt: G019W_DONE / G019W_ABORT.
set -u
KIT=$HOME/kit5/kit
BIN=$HOME/g019w/bin
cd "$KIT" || exit 2
sha256sum -c SHA256SUMS > $HOME/g019w/kit-sha-check.txt 2>&1 || { echo "kit SHA256SUMS check failed"; exit 2; }
(cd "$BIN" && sha256sum -c SHA256SUMS) > $HOME/g019w/bin-sha-check.txt 2>&1 || { echo "binary SHA256SUMS check failed"; exit 2; }
export SNAP_MDB=/var/lib/hdd/s3106400/testnet/lmdb/data.mdb
export DATA_DIR=/var/lib/hdd/run
export PEER=${PEER:?host:port of the peer}
export OUT_BASE=$HOME/hddruns
RUN=$KIT/hdd_run.sh
BIN_A=$BIN/monerod-pcA-d80596ad1
BIN_W=$BIN/monerod-pcW-cc0dd9af4
ORDER="A W W A W A A W"
RUN_TIMEOUT_S=4800
sudo -n true 2> /dev/null || { echo "sudo needs a password"; exit 2; }
ST=$OUT_BASE/g019w-$(date -u +%Y%m%dT%H%M%SZ); mkdir -p "$ST"
lg() { echo "$*" | tee -a "$ST/log.txt"; }
lg "g019w start $(date -u +%FT%TZ); order $ORDER; per-run timeout $RUN_TIMEOUT_S s; MEM_MAX none; WARM_DBS none"
lg "run script $RUN ($(sha256sum "$RUN" | cut -c1-16)); this script $(sha256sum "$0" | cut -c1-16)"
lg "BIN_A $BIN_A ($(sha256sum "$BIN_A" | cut -c1-16)); BIN_W $BIN_W ($(sha256sum "$BIN_W" | cut -c1-16))"
lg "SNAP_MDB $SNAP_MDB ($(stat -c '%s bytes, mtime %y' "$SNAP_MDB"))"
lg "VM: nproc $(nproc); $(awk '/^(MemTotal|MemAvailable|SwapTotal)/ {printf "%s %s kB; ", $1, $2}' /proc/meminfo)kernel $(uname -r)"
i=0
for a in $ORDER; do
  i=$((i + 1)); o=$ST/run$i-$a.out
  case $a in A) b=$BIN_A ;; W) b=$BIN_W ;; esac
  lg "run $i arm $a $(date -u +%FT%TZ)"
  env TIMEOUT_S="$RUN_TIMEOUT_S" bash "$RUN" "g019w-r$i-$a" "$b" > "$o" 2>&1; rc=$?
  d=$(grep -oE 'HDD_RUN_DONE .*' "$o" | cut -d' ' -f2)
  [ $rc -eq 0 ] && [ -n "$d" ] || { tail -5 "$o" | tee -a "$ST/log.txt"; lg "G019W_ABORT run $i arm $a rc=$rc"; exit 1; }
  grep -hE '^(RESULT|IOSTAT|WINDOW) ' "$d/summary.txt" | sed "s/^/run$i-$a /" >> "$ST/results.txt"
  echo "$d" >> "$ST/rundirs.txt"
  lg "done run $i arm $a: $(grep -h '^RESULT' "$d/summary.txt" | grep -oE ' (top|launch_to_top_s|rpc_s|launch_to_rpc_s|wall_s|outcome|hash_at_[0-9]+)=[^ ]*' | paste -sd' ')"
done
lg "G019W_DONE $(date -u +%FT%TZ) $ST"
